#!/usr/bin/env node
'use strict'

// Precompiles the vendored S2 schemas (src/lib/s2/s2-json-schema/) into a standalone,
// dependency-free validator module at src/lib/s2/schema-validators.generated.js - checked into
// git, regenerated by re-running this script whenever the vendored schemas change.
//
// Why: `ajv` itself is ~2.3M installed - about 5x this project's entire other production
// dependency footprint combined - which matters on the disk-constrained device this package
// ships to. `ajv`/`ajv-formats` are devDependencies, used only here at build/generation time.
// The generated output only needs the tiny `ajv/dist/runtime/*` helper files, which this script
// also vendors into src/lib/s2/ajv-runtime/ so the device never needs `ajv` installed at all.

const fs = require('fs')
const path = require('path')
const Ajv2020 = require('ajv/dist/2020').default
const addFormats = require('ajv-formats').default
const standaloneCode = require('ajv/dist/standalone').default

const root = path.join(__dirname, '..')
const schemaRoot = path.join(root, 'src', 'lib', 's2', 's2-json-schema')
const messagesDir = path.join(schemaRoot, 'messages')
const schemasDir = path.join(schemaRoot, 'schemas')
const outFile = path.join(root, 'src', 'lib', 's2', 'schema-validators.generated.js')
const runtimeOutDir = path.join(root, 'src', 'lib', 's2', 'ajv-runtime')

const ajv = new Ajv2020({ allErrors: true, strict: false, code: { source: true } })
addFormats(ajv)

function loadDir (dir) {
  for (const name of fs.readdirSync(dir)) {
    if (!name.endsWith('.schema.json')) continue
    const schema = JSON.parse(fs.readFileSync(path.join(dir, name), 'utf8'))
    ajv.addSchema(schema, schema.$id)
  }
}
loadDir(schemasDir)
loadDir(messagesDir)

// One exported validator per message-level schema (not the shared schemas/ subtypes, which are
// only ever reached via $ref, never validated directly). Export names must be valid JS
// identifiers, so a message_type containing "." (e.g. "OMBC.SystemDescription") gets sanitized -
// messageTypeToExport (embedded below) maps the real message_type string back to its export name.
const refs = {}
const messageTypeToExport = {}
for (const name of fs.readdirSync(messagesDir)) {
  if (!name.endsWith('.schema.json')) continue
  const schema = JSON.parse(fs.readFileSync(path.join(messagesDir, name), 'utf8'))
  const messageType = name.replace(/\.schema\.json$/, '')
  const exportName = 'v_' + messageType.replace(/[^a-zA-Z0-9_]/g, '_')
  refs[exportName] = schema.$id
  messageTypeToExport[messageType] = exportName
}

let moduleCode = standaloneCode(ajv, refs)

// Rewrite ajv's own runtime-helper require paths, and ajv-formats' formats data require, to the
// vendored copies below - so the generated file has no dependency on `ajv` or `ajv-formats` (which
// itself depends on the full `ajv` package - see VENDORED.md) being installed at all.
moduleCode = moduleCode.replace(/require\("ajv\/dist\/runtime\/([^"]+)"\)/g, 'require("./ajv-runtime/$1")')
moduleCode = moduleCode.replace(/require\("ajv-formats\/dist\/formats(?:\.js)?"\)/g, 'require("./ajv-runtime/formats")')

const header = `'use strict'\n` +
  `// AUTO-GENERATED by scripts/generate-schema-validators.js - do not edit by hand.\n` +
  `// Regenerate with: npm run generate-schema-validators (after changing src/lib/s2/s2-json-schema/).\n\n`
const footer = `\nmodule.exports.messageTypeToExport = ${JSON.stringify(messageTypeToExport, null, 2)}\n`

fs.writeFileSync(outFile, header + moduleCode + footer)

// Vendor the small runtime files the generated code actually requires - ajv's own dist/runtime/*
// helpers, plus ajv-formats' self-contained (zero further requires) formats.js if format checks
// (e.g. date-time) are used, under whichever name the generated code now requires them as.
fs.mkdirSync(runtimeOutDir, { recursive: true })
const ajvRuntimeDir = path.join(path.dirname(require.resolve('ajv/package.json')), 'dist', 'runtime')
const ajvFormatsFile = path.join(path.dirname(require.resolve('ajv-formats/package.json')), 'dist', 'formats.js')
const neededHelpers = new Set([...moduleCode.matchAll(/require\("\.\/ajv-runtime\/([^"]+)"\)/g)].map((m) => m[1]))
for (const helper of neededHelpers) {
  const source = helper === 'formats' ? ajvFormatsFile : path.join(ajvRuntimeDir, `${helper}.js`)
  fs.copyFileSync(source, path.join(runtimeOutDir, `${helper}.js`))
}

console.log(`generate-schema-validators: wrote ${path.relative(root, outFile)} (${Object.keys(refs).length} validators, ${neededHelpers.size} vendored runtime helper(s))`)
